def time_difference(self, track_point: 'GPXTrackPoint') ->Optional[float]:
    if not self.time or not track_point or not track_point.time:
        return None

    time_1 = self.time
    time_2 = track_point.time

    if time_1 == time_2:
        return 0

    if time_1 > time_2:
        delta = time_1 - time_2
    else:
        delta = time_2 - time_1

    return mod_utils.total_seconds(delta)
